<template>
  <div>
    <PageHeader title="对账" description="只覆盖订单金额、实收金额与数量差异的业务确认，不替代发票、税务或付款结算。">
      <template #actions><el-button v-if="auth.role === 'BUYER'" type="primary" :icon="Plus" @click="openCreate">创建对账</el-button><el-button :icon="Refresh" :loading="loading" @click="load">刷新对账</el-button></template>
    </PageHeader>
    <div class="metric-grid recon-metrics"><article class="metric-item" style="--metric-color: var(--lm-warning)"><div class="metric-label">待核对</div><div class="metric-value"><span>{{ pendingCount }}</span><span class="metric-unit">笔</span></div><div class="metric-foot"><span>需要业务确认</span><span>当前范围</span></div></article><article class="metric-item" style="--metric-color: var(--lm-danger)"><div class="metric-label">差异金额</div><div class="metric-value"><span>¥{{ differenceAmount.toLocaleString('zh-CN', { minimumFractionDigits: 0 }) }}</span></div><div class="metric-foot"><span>负数代表实收少于订单</span><span>未关闭</span></div></article><article class="metric-item" style="--metric-color: var(--lm-success)"><div class="metric-label">已确认</div><div class="metric-value"><span>{{ confirmedCount }}</span><span class="metric-unit">笔</span></div><div class="metric-foot"><span>已完成业务确认</span><span>可追溯</span></div></article><article class="metric-item" style="--metric-color: var(--lm-blue)"><div class="metric-label">口径</div><div class="metric-value"><span>订单</span></div><div class="metric-foot"><span>数量 × 单价</span><span>V1 范围</span></div></article></div>
    <section class="surface reconciliation-table"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索对账单、订单号或供应商" :prefix-icon="Search" /><el-select v-model="statusFilter" clearable placeholder="全部状态" style="width: 145px"><el-option v-for="item in statusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><span class="toolbar-spacer"></span><span class="toolbar-meta">{{ filtered.length }} 笔对账</span></div><div v-if="errorMessage" class="inline-error"><WarningFilled />{{ errorMessage }}</div><div v-if="loading && !records.length" class="table-loading"><div v-for="i in 3" :key="i" class="skeleton" style="height: 45px"></div></div><div v-else-if="!filtered.length"><EmptyState title="暂无对账记录" description="收货完成后会根据订单与实收事实生成对账记录。" action-text="查看收货" @action="router.push('/receipts')" /></div><div v-else class="table-wrap"><el-table :data="filtered" stripe><el-table-column prop="reconciliationNo" label="对账单号" width="175" /><el-table-column prop="orderNo" label="关联订单" width="170" /><el-table-column prop="supplierName" label="供应商" min-width="175" /><el-table-column label="订单金额" width="135" align="right"><template #default="scope"><span class="number">¥{{ scope.row.orderAmount.toLocaleString('zh-CN', { minimumFractionDigits: 2 }) }}</span></template></el-table-column><el-table-column label="实收金额" width="135" align="right"><template #default="scope"><span class="number">¥{{ scope.row.receivedAmount.toLocaleString('zh-CN', { minimumFractionDigits: 2 }) }}</span></template></el-table-column><el-table-column label="差异金额" width="135" align="right"><template #default="scope"><span class="number" :class="scope.row.differenceAmount < 0 ? 'danger-number' : scope.row.differenceAmount > 0 ? 'warning-number' : 'safe-number'">{{ scope.row.differenceAmount > 0 ? '+' : '' }}¥{{ scope.row.differenceAmount.toLocaleString('zh-CN', { minimumFractionDigits: 2 }) }}</span></template></el-table-column><el-table-column label="状态" width="115"><template #default="scope"><StatusBadge :label="statusMeta(scope.row.status).label" :tone="statusMeta(scope.row.status).tone" /></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="170" /><el-table-column label="操作" width="270" fixed="right"><template #default="scope"><el-button v-if="auth.role === 'SUPPLIER' && (scope.row.status === 'PENDING' || scope.row.status === 'IN_REVIEW')" link type="primary" @click="openAction(scope.row, 'CONFIRM')">确认</el-button><el-button v-if="auth.role === 'SUPPLIER' && (scope.row.status === 'PENDING' || scope.row.status === 'IN_REVIEW')" link type="danger" @click="openAction(scope.row, 'DISPUTE')">提出争议</el-button><el-button v-if="auth.role === 'BUYER' && scope.row.status === 'DISPUTED'" link type="primary" @click="openAction(scope.row, 'RESOLVE')">处理争议</el-button><el-button v-if="auth.role === 'BUYER' && ['CONFIRMED', 'RESOLVED'].includes(scope.row.status)" link type="primary" @click="openAction(scope.row, 'COMPLETE')">完成对账</el-button><el-button v-if="!((auth.role === 'SUPPLIER' && ['PENDING', 'IN_REVIEW'].includes(scope.row.status)) || (auth.role === 'BUYER' && (scope.row.status === 'DISPUTED' || ['CONFIRMED', 'RESOLVED'].includes(scope.row.status))) )" link type="primary" @click="show(scope.row)">查看</el-button></template></el-table-column></el-table></div></section>
    <el-dialog v-model="dialogVisible" :title="actionTitle" width="460px"><template v-if="selected"><div class="recon-context"><div><span>对账单</span><strong>{{ selected.reconciliationNo }}</strong></div><div><span>差异金额</span><strong class="danger-number">¥{{ Math.abs(selected.differenceAmount).toLocaleString('zh-CN', { minimumFractionDigits: 2 }) }}</strong></div></div><div class="inline-note">确认仅表示采购业务对订单与实收差异达成一致，不代表财务付款完成。</div><el-form label-position="top" style="margin-top: 17px"><el-form-item label="备注"><el-input v-model="note" type="textarea" :rows="3" placeholder="提出争议或解决争议时必须填写原因" /></el-form-item></el-form></template><template #footer><el-button @click="dialogVisible = false">取消</el-button><el-button type="primary" :loading="updating" @click="saveAction">{{ actionLabel }}</el-button></template></el-dialog>
    <el-dialog v-model="createVisible" title="创建对账" width="460px"><el-form ref="createFormRef" :model="createForm" label-position="top"><el-form-item label="已收货订单"><el-select v-model="createForm.orderId" filterable style="width:100%" placeholder="选择 RECEIVED 订单"><el-option v-for="item in receivedOrders" :key="item.id" :label="`${item.orderNo} · ${item.supplierName}`" :value="item.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="creating" @click="createReconciliation">创建</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Plus, Refresh, Search, WarningFilled } from '@element-plus/icons-vue'
import { useRouter } from 'vue-router'
import PageHeader from '@/components/PageHeader.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import EmptyState from '@/components/EmptyState.vue'
import { useAuthStore } from '@/stores/auth'
import { apiList, apiMutate, extractApiError } from '@/services/api'
import { demoReconciliations } from '@/services/demo'
import { mapOrder, mapReconciliation } from '@/services/mappers'
import type { PurchaseOrder, ReconciliationRecord } from '@/types'

const router = useRouter(); const auth = useAuthStore(); const records = ref<ReconciliationRecord[]>([]); const orders = ref<PurchaseOrder[]>([]); const keyword = ref(''); const statusFilter = ref(''); const loading = ref(false); const updating = ref(false); const creating = ref(false); const errorMessage = ref(''); const selected = ref<ReconciliationRecord>(); const dialogVisible = ref(false); const createVisible = ref(false); const note = ref(''); const action = ref<'CONFIRM' | 'DISPUTE' | 'RESOLVE' | 'COMPLETE'>('CONFIRM'); const createForm = ref({ orderId: '' }); const createFormRef = ref()
const statusOptions = [{ value: 'PENDING', label: '待处理' }, { value: 'IN_REVIEW', label: '核对中' }, { value: 'CONFIRMED', label: '已确认' }, { value: 'DISPUTED', label: '有争议' }, { value: 'RESOLVED', label: '已解决' }, { value: 'COMPLETED', label: '已完成' }, { value: 'CLOSED', label: '已关闭' }]
const filtered = computed(() => records.value.filter((item) => (!statusFilter.value || item.status === statusFilter.value) && (!keyword.value || `${item.reconciliationNo}${item.orderNo}${item.supplierName}`.toLowerCase().includes(keyword.value.toLowerCase())))); const pendingCount = computed(() => records.value.filter((item) => ['PENDING', 'IN_REVIEW', 'DISPUTED'].includes(item.status)).length); const confirmedCount = computed(() => records.value.filter((item) => ['CONFIRMED', 'RESOLVED', 'COMPLETED', 'CLOSED'].includes(item.status)).length); const differenceAmount = computed(() => records.value.filter((item) => !['CLOSED', 'COMPLETED'].includes(item.status)).reduce((sum, item) => sum + item.differenceAmount, 0))
const receivedOrders = computed(() => orders.value.filter((item) => item.status === 'RECEIVED'))
const actionTitle = computed(() => ({ CONFIRM: '确认对账', DISPUTE: '提出对账争议', RESOLVE: '处理对账争议', COMPLETE: '完成对账' } as Record<string, string>)[action.value])
const actionLabel = computed(() => ({ CONFIRM: '确认', DISPUTE: '提出争议', RESOLVE: '解决争议', COMPLETE: '完成对账' } as Record<string, string>)[action.value])
async function load() { loading.value = true; errorMessage.value = ''; try { const result = await apiList<ReconciliationRecord>({ method: 'GET', url: '/reconciliations' }, mapReconciliation, () => demoReconciliations); records.value = result.records } catch (error) { errorMessage.value = extractApiError(error) } finally { loading.value = false } }
async function openCreate() { if (auth.role !== 'BUYER') return; try { orders.value = (await apiList<PurchaseOrder>({ method: 'GET', url: '/purchase-orders' }, mapOrder)).records; createForm.value = { orderId: receivedOrders.value[0]?.id || '' }; createVisible.value = true; if (!receivedOrders.value.length) ElMessage.info('当前没有 RECEIVED 订单可创建对账。') } catch (error) { ElMessage.error(extractApiError(error)) } }
async function createReconciliation() { if (!createForm.value.orderId) { ElMessage.error('请选择已收货订单'); return } const item = orders.value.find((entry) => entry.id === createForm.value.orderId); if (!item) return; creating.value = true; try { const raw = await apiMutate<unknown>({ method: 'POST', url: '/reconciliations', data: { orderId: Number(item.id), orderVersion: item.version ?? 0 } }); const result = mapReconciliation(raw); records.value = [result, ...records.value]; createVisible.value = false; ElMessage.success('对账记录已创建') } catch (error) { ElMessage.error(extractApiError(error)) } finally { creating.value = false } }
function openAction(item: ReconciliationRecord, next: 'CONFIRM' | 'DISPUTE' | 'RESOLVE' | 'COMPLETE') { selected.value = item; action.value = next; note.value = ''; dialogVisible.value = true }
function show(item: ReconciliationRecord) { ElMessage.info(`${item.reconciliationNo} 状态为${statusMeta(item.status).label}`) }
async function saveAction() { if (!selected.value) return; if (['DISPUTE', 'RESOLVE'].includes(action.value) && !note.value.trim()) { ElMessage.error('提出或解决争议必须填写备注'); return } const item = selected.value; updating.value = true; try { const raw = await apiMutate<unknown>({ method: 'POST', url: `/reconciliations/${item.id}/actions`, data: { action: action.value, expectedVersion: item.version ?? 0, note: note.value } }, () => ({ ...item, status: action.value === 'CONFIRM' ? 'CONFIRMED' : action.value === 'DISPUTE' ? 'DISPUTED' : action.value === 'RESOLVE' ? 'RESOLVED' : 'COMPLETED', updatedAt: new Date().toLocaleString('zh-CN', { hour12: false }) })); const result = mapReconciliation(raw); records.value = records.value.map((entry) => entry.id === result.id ? result : entry); selected.value = result; dialogVisible.value = false; ElMessage.success('对账动作已提交并写入审计') } catch (error) { ElMessage.error(extractApiError(error)) } finally { updating.value = false } }
function statusMeta(value: ReconciliationRecord['status']) { return ({ PENDING: { label: '待处理', tone: 'warning' }, IN_REVIEW: { label: '核对中', tone: 'warning' }, CONFIRMED: { label: '已确认', tone: 'success' }, DISPUTED: { label: '有争议', tone: 'danger' }, RESOLVED: { label: '已解决', tone: 'success' }, COMPLETED: { label: '已完成', tone: 'success' }, CLOSED: { label: '已关闭', tone: 'neutral' } } as Record<string, { label: string; tone: 'neutral' | 'warning' | 'success' | 'blue' | 'danger' }>)[value] || { label: value, tone: 'neutral' } }
onMounted(load)
</script>

<style scoped>
.recon-metrics { grid-template-columns: repeat(4, minmax(0, 1fr)); }.reconciliation-table { overflow: hidden; }.toolbar-meta { color: var(--lm-muted); font-size: 11px; }.number { font-variant-numeric: tabular-nums; }.danger-number { color: var(--lm-danger); }.warning-number { color: var(--lm-warning); }.safe-number { color: var(--lm-success); }.recon-context { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 18px; }.recon-context > div { display: grid; gap: 6px; padding: 12px 13px; background: var(--lm-surface); border: 1px solid var(--lm-border); }.recon-context span { color: var(--lm-muted); font-size: 11px; }.recon-context strong { font-size: 15px; font-variant-numeric: tabular-nums; }
@media (max-width: 900px) { .recon-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 600px) { .recon-metrics { grid-template-columns: 1fr; } .recon-context { grid-template-columns: 1fr; } }
</style>
